(L/'results.json').write_text(json.dumps(res,indent=2,ensure_ascii=False)+'\n')
receipts=[]
for p in sorted((L/'sources').glob('*/receipt.json')):
 r=json.loads(p.read_text());b=(p.parent/'body').read_bytes();assert h(b)==r['sha256'];receipts.append({'receipt':str(p.relative_to(L)),**r})
